// Generates everything derived from the contracts into server/contracts/generated:
// input validators, TypeScript types, a fetch client and a fake server, and the
// published OpenAPI document openapi/v1.json.
// Generated files are committed; server/contracts/contracts.test.ts fails when
// they differ from a fresh run. Usage: pnpm contracts:generate
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import type { TSchema } from "@sinclair/typebox";
import { TypeCompiler } from "@sinclair/typebox/compiler";

import {
  API_VERSION,
  checkInventory,
  FALLBACK,
  INVENTORY,
  INVENTORY_SOURCE,
  PENDING,
  ROUTES,
  type RouteContract,
  type Vector,
} from "../server/contracts/index.ts";

export const OUT_DIR = fileURLToPath(new URL("../server/contracts/generated/", import.meta.url));
/** The success and error vectors (U7); the fake server answers with them. */
const VECTORS_DIR = fileURLToPath(new URL("../server/contracts/vectors/", import.meta.url));
/** The published API document; scripts/check-breaking.ts compares it with the base branch. */
export const OPENAPI_FILE = fileURLToPath(new URL("../openapi/v1.json", import.meta.url));
const HEADER =
  "// GENERATED by scripts/generate-contracts.ts from server/contracts. Do not edit.\n";
type Schema = TSchema & Record<string, unknown>;

const ANY_PARAMETER = "function check(value: any): boolean {";
const ANY_ITEM = "(array) => { for(const value: any of array)";
const sorted = (): RouteContract[] => [...ROUTES].sort((a, b) => (a.id < b.id ? -1 : 1));
const json = (value: unknown) => `${JSON.stringify(value, null, 2)}\n`;
const plain = (schema: TSchema): unknown => JSON.parse(JSON.stringify(schema));

/** TypeScript for the subset of JSON Schema the contracts use; anything else is refused. */
function ts(schema: Schema): string {
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  if (Array.isArray(schema.anyOf)) return (schema.anyOf as Schema[]).map(ts).join(" | ");
  switch (schema.type) {
    case "string":
      return "string";
    case "number":
    case "integer":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "array":
      return `(${ts(schema.items as Schema)})[]`;
    case "object": {
      const required = new Set((schema.required as string[] | undefined) ?? []);
      const props = Object.entries((schema.properties ?? {}) as Record<string, Schema>);
      const body = props
        .map(([k, v]) => `${JSON.stringify(k)}${required.has(k) ? "" : "?"}: ${ts(v)}`)
        .join("; ");
      return `{ ${body}${schema.additionalProperties === false ? "" : `${body ? "; " : ""}[key: string]: unknown`} }`;
    }
  }
  throw new Error(`unsupported schema: ${JSON.stringify(schema)}`);
}

function openapi(routes: RouteContract[]): unknown {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const r of routes) {
    const parameters = (["path", "query"] as const).flatMap((where) => {
      const obj = where === "path" ? r.request.params : r.request.query;
      const required = new Set(obj?.required ?? []);
      return Object.entries(obj?.properties ?? {}).map(([name, s]) => ({
        name,
        in: where,
        required: where === "path" || required.has(name),
        schema: plain(s),
      }));
    });
    const responses: Record<string, unknown> = {};
    for (const s of r.responses) {
      responses[String(s.status)] = {
        description: s.description,
        ...(s.headers
          ? {
              headers: Object.fromEntries(
                s.headers.map((h) => [h, { schema: { type: "string" } }]),
              ),
            }
          : {}),
        ...(s.body ? { content: { "application/json": { schema: plain(s.body) } } } : {}),
      };
    }
    for (const status of [...new Set(r.errors.map((e) => e.status))]) {
      const errs = r.errors.filter((e) => e.status === status);
      const bodies = errs.map((e) => (e.body === undefined ? errorSchema(e.code) : e.body));
      const json = bodies.filter((b): b is TSchema => typeof b === "object").map(plain);
      responses[String(status)] = {
        description: errs.map((e) => e.code).join(", "),
        ...(json.length
          ? {
              content: {
                "application/json": { schema: json.length === 1 ? json[0] : { oneOf: json } },
              },
            }
          : {}),
        ...(bodies.includes("html") ? { "x-html-page": true } : {}),
      };
    }
    (paths[r.path] ??= {})[r.method.toLowerCase()] = {
      operationId: r.id,
      summary: r.summary,
      "x-access": r.access,
      "x-inventory": r.inventory,
      ...(parameters.length ? { parameters } : {}),
      ...(r.request.body
        ? {
            requestBody: {
              required: true,
              content: { [r.request.contentType ?? ""]: { schema: plain(r.request.body) } },
            },
            "x-max-body-bytes": r.request.maxBodyBytes,
          }
        : {}),
      responses,
      "x-errors": r.errors.map(({ status, code, key }) => ({ status, code, key })),
    };
  }
  const { status, code, key } = FALLBACK.error;
  return {
    openapi: "3.1.0",
    info: { title: "Ductura API", version: API_VERSION, "x-inventory-source": INVENTORY_SOURCE },
    "x-fallback": { status, code, key, inventory: FALLBACK.inventory },
    paths,
  };
}

function errorSchema(code: string): TSchema {
  return {
    type: "object",
    additionalProperties: false,
    required: ["error"],
    properties: { error: { const: code, type: "string" } },
  } as unknown as TSchema;
}

function types(routes: RouteContract[]): string {
  const ops = routes.map((r) => {
    const part = (s: TSchema | undefined) => (s ? ts(s as Schema) : "undefined");
    // Declared headers are optional: a browser hides them on an opaque redirect.
    const head = (names: readonly string[] = []) =>
      `{ ${names.map((h) => `${JSON.stringify(h)}?: ${h === "set-cookie" ? "string[]" : "string"}`).join("; ")} }`;
    const ok = r.responses
      .map((s) => `{ status: ${s.status}; body: ${part(s.body)}; headers: ${head(s.headers)} }`)
      .join(" | ");
    const codes = r.errors.map((e) => JSON.stringify(e.code)).join(" | ") || "never";
    return `  ${JSON.stringify(r.id)}: {\n    params: ${part(r.request.params)};\n    query: ${part(r.request.query)};\n    body: ${part(r.request.body)};\n    success: ${ok};\n    errorCode: ${codes};\n  };`;
  });
  return `${HEADER}\nexport type Operations = {\n${ops.join("\n")}\n};\n\nexport type OperationId = keyof Operations;\n`;
}

function routeTable(routes: RouteContract[]): string {
  const rows = routes.map((r) => {
    const codes = Object.fromEntries(
      [...new Set(r.errors.map((e) => e.status))].map((s) => [
        s,
        r.errors.filter((e) => e.status === s).map((e) => e.code),
      ]),
    );
    return `  ${JSON.stringify(r.id)}: { method: ${JSON.stringify(r.method)}, path: ${JSON.stringify(r.path)}, body: ${JSON.stringify(r.request.contentType ?? null)}, headers: ${JSON.stringify([...new Set(r.responses.flatMap((s) => s.headers ?? []))])}, errors: ${JSON.stringify(codes)} },`;
  });
  return `export const ROUTE_TABLE = {\n${rows.join("\n")}\n} as const;\n`;
}

/**
 * One request schema as a TypeScript check function expression, compiled
 * ahead of time. Throws for output the cleanup below does not expect.
 */
export function compileValidator(schema: TSchema, where: string): string {
  const raw = TypeCompiler.Code(schema, [], { language: "typescript" }).replace(/^return /, "");
  // TypeBox types the parameter as any. Every check tests for a plain object
  // first, so a record type is enough and keeps any out of the output.
  const code = raw
    .replace(ANY_PARAMETER, `function check(value: Record<string, unknown>): boolean {`)
    // An array's items are checked one by one after Array.isArray, so unknown is enough.
    .replaceAll(ANY_ITEM, "(array: unknown[]) => { for(const value of array)")
    // TypeBox names a pattern's regex local_N; the naming rule wants camelCase.
    // Only its declarations and .test( calls: a field or pattern text keeps local_N as it is.
    .replace(/^(\s*const )local_(\d+) = /gm, "$1local$2 = ")
    .replace(/\blocal_(\d+)\.test\(/g, "local$1.test(")
    // Number.isInteger does not narrow unknown; typeof first lets the bounds compile.
    .replace(
      /Number\.isInteger\((value\['\w+'\])\)/g,
      "(typeof $1 === 'number' && Number.isInteger($1))",
    );
  if (code === raw || code.includes(": any"))
    throw new Error(`unexpected validator shape for ${where}`);
  // A pattern compiles to a `const local_N` regex before the function: keep it in a closure.
  return code.startsWith("function ") ? `(${code})` : `(() => {\n${code}\n})()`;
}

function validators(routes: RouteContract[]): string {
  const rows = routes.flatMap((r) =>
    (["params", "query", "body"] as const).flatMap((part) => {
      const schema = r.request[part];
      if (!schema) return [];
      const value = compileValidator(schema, `${r.id}:${part}`);
      return [`  ${JSON.stringify(`${r.id}:${part}`)}: ${value.replace(/\n/g, "\n  ")},`];
    }),
  );
  return `${HEADER}// Input validators compiled ahead of time from the request schemas.\n\nexport const VALIDATORS: Readonly<Record<string, (value: Record<string, unknown>) => boolean>> = {\n${rows.join("\n")}\n};\n\nexport function validateInput(id: string, part: "params" | "query" | "body", value: unknown): boolean {\n  const check = VALIDATORS[\`\${id}:\${part}\`];\n  // Each check tests for a plain object before reading a field.\n  if (check !== undefined) return check(value as Record<string, unknown>);
  // No schema: no body, and for params or query nothing or an empty object.
  if (value === undefined) return true;
  return part !== "body" && typeof value === "object" && value !== null && !Array.isArray(value) && Object.keys(value).length === 0;\n}\n`;
}

function contractRoutes(): RouteContract[] {
  const problems = checkInventory(ROUTES, INVENTORY, PENDING, FALLBACK.inventory);
  if (problems.length) throw new Error(`contracts are not valid:\n${problems.join("\n")}`);
  return sorted();
}

/** openapi/v1.json as written to disk. */
export const openapiJson = (): string => json(openapi(contractRoutes()));
export const openapiDocument = (): unknown => JSON.parse(openapiJson());

export function generate(): Record<string, string> {
  const routes = contractRoutes();
  return {
    "client.ts": `${HEADER}${CLIENT_PREAMBLE}\n${routeTable(routes)}${CLIENT_BODY}`,
    // Its own folder: it needs node:http, and generated/index.ts must load in a
    // browser. It imports nothing outside the folder, so U9 can move it as it is.
    "fake-server/index.ts": `${HEADER}${FAKE_PREAMBLE}\n${routeTable(routes)}\nconst FALLBACK_CODE = ${JSON.stringify(FALLBACK.error.code)};\n${FAKE_BODY}`,
    "fake-server/vectors.json": fakeVectors(routes),
    "types.ts": types(routes),
    "validate.ts": validators(routes),
    "index.ts": INDEX,
  };
}

const INDEX = `${HEADER}export { createClient, type Result } from "./client.ts";
export type { OperationId, Operations } from "./types.ts";
export { VALIDATORS, validateInput } from "./validate.ts";
`;

const CLIENT_PREAMBLE = `// Fetch client for /api/v1. Works from any runtime with fetch, not only a browser.
import type { OperationId, Operations } from "./types.ts";
`;

const CLIENT_BODY = `
type Input<Id extends OperationId> = Pick<Operations[Id], "params" | "query" | "body">;
export type Result<Id extends OperationId> =
  | (Operations[Id]["success"] & { ok: true })
  | { ok: false; status: number; code: Operations[Id]["errorCode"] | "unexpected" };

export function createClient(baseUrl: string, fetchImpl: typeof fetch = fetch) {
  return async function call<Id extends OperationId>(id: Id, input: Input<Id>): Promise<Result<Id>> {
    const route = ROUTE_TABLE[id];
    const params = (input.params ?? {}) as Record<string, string>;
    let path: string = route.path.replace(/\\{(\\w+)\\}/g, (match, name: string) => encodeURIComponent(params[name] ?? ""));
    const query = new URLSearchParams(
      Object.entries((input.query ?? {}) as Record<string, string | undefined>).filter((e): e is [string, string] => e[1] !== undefined),
    );
    if (query.size > 0) path += \`?\${query.toString()}\`;
    const init: RequestInit = { method: route.method, redirect: "manual" };
    if (route.body === "application/json") init.body = JSON.stringify(input.body);
    if (route.body === "application/x-www-form-urlencoded") init.body = new URLSearchParams(input.body as Record<string, string>).toString();
    if (route.body !== null) init.headers = { "content-type": route.body };
    const res = await fetchImpl(new URL(path, baseUrl), init);
    // In a browser a manual redirect is opaque (status 0); every contracted redirect is a 303.
    if (res.type === "opaqueredirect") return { ok: true, status: 303, body: undefined, headers: {} } as Result<Id>;
    const body: unknown = res.headers.get("content-type")?.startsWith("application/json") ? await res.json() : undefined;
    if (res.status < 400) {
      // The headers the contract says callers rely on (location, set-cookie), nothing else.
      const headers: Record<string, string | string[]> = {};
      for (const name of route.headers as readonly string[]) {
        const value = name === "set-cookie" ? res.headers.getSetCookie() : res.headers.get(name);
        if (value !== null && value.length > 0) headers[name] = value;
      }
      return { ok: true, status: res.status, body, headers } as Result<Id>;
    }
    const known = (route.errors as Record<number, readonly string[] | undefined>)[res.status] ?? [];
    // The code is in "error"; readiness carries it in "status" ({status: "draining"}).
    const fields = body && typeof body === "object" ? (body as { error?: unknown; status?: unknown }) : {};
    const sent = fields.error ?? fields.status;
    // A body without a code takes the only code of its status; an unknown code is never renamed.
    const code = typeof sent === "string" ? (known.includes(sent) ? sent : "unexpected") : known.length === 1 ? known[0] : "unexpected";
    return { ok: false, status: res.status, code } as Result<Id>;
  };
}
`;

/**
 * The vectors of every route in route order, then file order. Each file must
 * name its route; vectors.test.ts checks the rest (format, schemas, coverage).
 * JSON data, not a .ts file: the vectors spell out made-up session cookies, and
 * server/session/ended-mark-coverage.test.ts rightly refuses those in server code.
 */
function fakeVectors(routes: RouteContract[]): string {
  const rows = routes.flatMap((r) => {
    const file = JSON.parse(readFileSync(join(VECTORS_DIR, `${r.id}.json`), "utf8")) as {
      route?: unknown;
      vectors?: unknown;
    };
    if (file.route !== r.id || !Array.isArray(file.vectors))
      throw new Error(`vectors/${r.id}.json is not the vectors file of ${r.id}`);
    return (file.vectors as Vector[]).map((v) => ({
      route: r.id,
      name: v.name,
      request: v.request,
      response: v.response,
    }));
  });
  return json(rows);
}

const FAKE_PREAMBLE = `// Fake server from the contracts (U8). A request that matches a vector of its
// route gets exactly that vector's answer; a contracted route with no matching
// vector answers 501, a known path with another method 405, anything else the
// fallback. Test code only: eslint.config.ts keeps it out of production code.
import { readFileSync } from "node:fs";
import { createServer, type Server } from "node:http";
`;

// Written out as it is: no template literals inside, so String.raw keeps every backslash.
const FAKE_BODY = String.raw`
export type FakeVector = {
  readonly route: string;
  readonly name: string;
  readonly request: {
    readonly params?: Readonly<Record<string, string>>;
    readonly query?: Readonly<Record<string, string>>;
    readonly headers?: Readonly<Record<string, string>>;
    readonly body?: unknown;
    readonly rawBody?: string;
  };
  readonly response: {
    readonly status: number;
    readonly contentType?: string;
    readonly headers?: Readonly<Record<string, string | readonly string[]>>;
    readonly body?: unknown;
  };
};

/** The vectors of server/contracts/vectors (U7), in route order, then file order. */
export const VECTORS: readonly FakeVector[] = JSON.parse(
  readFileSync(new URL("./vectors.json", import.meta.url), "utf8"),
) as FakeVector[];

/** Picks a vector by name when several match one request (first in file order otherwise). */
export const FAKE_VECTOR_HEADER = "x-ductura-fake-vector";

export type FakeRequest = {
  readonly method: string;
  readonly url: string;
  readonly headers: Readonly<Record<string, string | readonly string[] | undefined>>;
  readonly body: Uint8Array;
};
export type FakeAnswer = {
  readonly status: number;
  readonly headers: Record<string, string | string[]>;
  readonly body: string;
};

const MATCHERS = Object.entries(ROUTE_TABLE).map(([id, r]) => ({
  id,
  method: r.method as string,
  body: r.body as string | null,
  names: [...r.path.matchAll(/\{(\w+)\}/g)].map((m) => m[1] ?? ""),
  pattern: new RegExp("^" + r.path.replace(/\{\w+\}/g, "([^/]+)") + "$"),
}));
type Matcher = (typeof MATCHERS)[number];

/**
 * The answer to one request. A vector matches when the path parameters and the
 * query equal its own, every header it names has its value (other headers are
 * ignored) and the body is the same: bytes for rawBody, JSON or form fields by
 * the route's content type for body, and empty when the vector has neither.
 */
export function answerFake(req: FakeRequest): FakeAnswer {
  const url = new URL(req.url, "http://fake.invalid");
  const onPath = MATCHERS.filter((m) => m.pattern.test(url.pathname));
  const route = onPath.find((m) => m.method === req.method);
  if (route === undefined) {
    return onPath.length > 0
      ? refusal(405, "method_not_allowed", { allow: onPath.map((m) => m.method).join(", ") })
      : refusal(404, FALLBACK_CODE, {});
  }
  const wanted = header(req.headers, FAKE_VECTOR_HEADER);
  const vector = VECTORS.find(
    (v) =>
      v.route === route.id &&
      (wanted === undefined || v.name === wanted) &&
      matches(route, v, url, req),
  );
  return vector === undefined ? refusal(501, "not_implemented", {}) : reply(vector);
}

function matches(route: Matcher, v: FakeVector, url: URL, req: FakeRequest): boolean {
  const found = route.pattern.exec(url.pathname) ?? [];
  const params = dictionary();
  try {
    route.names.forEach((name, i) => (params[name] = decodeURIComponent(found[i + 1] ?? "")));
  } catch {
    return false;
  }
  const query = fields(url.searchParams);
  if (!same(params, v.request.params ?? {}) || query === null || !same(query, v.request.query ?? {}))
    return false;
  for (const [name, value] of Object.entries(v.request.headers ?? {})) {
    if (header(req.headers, name) !== value) return false;
  }
  return sameBody(route.body, v.request, req.body);
}

function sameBody(type: string | null, expected: FakeVector["request"], body: Uint8Array): boolean {
  if (expected.rawBody !== undefined) return Buffer.compare(Buffer.from(expected.rawBody), body) === 0;
  if (expected.body === undefined) return body.length === 0;
  try {
    const text = new TextDecoder("utf-8", { fatal: true }).decode(body);
    if (type !== "application/x-www-form-urlencoded") return same(JSON.parse(text), expected.body);
    const form = fields(new URLSearchParams(text));
    return form !== null && same(form, expected.body);
  } catch {
    return false;
  }
}

/** An object without a prototype, so a field named __proto__ is a field like any other. */
function dictionary(): Record<string, string> {
  return Object.create(null) as Record<string, string>;
}

/** Query or form fields as an object; a repeated name matches no vector. */
function fields(search: URLSearchParams): Record<string, string> | null {
  const out = dictionary();
  for (const [name, value] of search) {
    if (Object.hasOwn(out, name)) return null;
    out[name] = value;
  }
  return out;
}

/** A header by name, whatever the case of the name the caller used. */
function header(headers: FakeRequest["headers"], name: string): string | undefined {
  const wanted = name.toLowerCase();
  const values = Object.entries(headers).flatMap(([key, value]) =>
    key.toLowerCase() !== wanted || value === undefined
      ? []
      : [typeof value === "string" ? value : value.join(", ")],
  );
  return values.length === 0 ? undefined : values.join(", ");
}

/** Equal JSON values, whatever the order of object keys. */
function same(a: unknown, b: unknown): boolean {
  return canonical(a) === canonical(b);
}

function canonical(value: unknown): string {
  if (Array.isArray(value)) return "[" + value.map(canonical).join(",") + "]";
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    const keys = Object.keys(record).sort();
    return "{" + keys.map((k) => JSON.stringify(k) + ":" + canonical(record[k])).join(",") + "}";
  }
  return String(JSON.stringify(value));
}

/** Exactly the vector: its status, the headers it names, its content type and body. */
function reply(v: FakeVector): FakeAnswer {
  const { status, contentType, headers = {}, body } = v.response;
  const sent: Record<string, string | string[]> = {};
  for (const [name, value] of Object.entries(headers)) sent[name] = typeof value === "string" ? value : [...value];
  if (contentType !== undefined) sent["content-type"] = contentType;
  const text = body === undefined ? "" : typeof body === "string" ? body : JSON.stringify(body);
  return { status, headers: sent, body: text };
}

function refusal(status: number, code: string, extra: Record<string, string>): FakeAnswer {
  return {
    status,
    headers: { "content-type": "application/json", "cache-control": "no-store", ...extra },
    body: JSON.stringify({ error: code }),
  };
}

export function createFakeServer(): Server {
  return createServer((req, res) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("error", () => res.destroy());
    req.on("end", () => {
      const out = answerFake({
        method: req.method ?? "GET",
        url: req.url ?? "/",
        headers: req.headers,
        body: Buffer.concat(chunks),
      });
      // Only the headers the vector names (Node still adds its framing headers).
      res.sendDate = false;
      res.writeHead(out.status, out.headers);
      res.end(out.body);
    });
  });
}
`;

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const files = generate();
  rmSync(OUT_DIR, { recursive: true, force: true });
  for (const [name, content] of Object.entries(files)) {
    mkdirSync(dirname(join(OUT_DIR, name)), { recursive: true });
    writeFileSync(join(OUT_DIR, name), content);
  }
  writeFileSync(OPENAPI_FILE, openapiJson());
  console.log(`contracts: ${Object.keys(files).length} files in ${OUT_DIR} and ${OPENAPI_FILE}`);
}
